package com.example.starter.hazmat.clock;

import java.time.Clock;
import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.ZoneOffset;

/**
 * 可控时钟：测试中可显式设定"当前时刻"，便于复算超时边界；默认使用系统时钟（Asia/Shanghai）。
 */
public class MutableClock extends Clock {

    /** 业务统一时区。 */
    public static final ZoneId ZONE = ZoneId.of("Asia/Shanghai");

    private volatile Instant instant;
    private volatile ZoneId zone = ZONE;

    public MutableClock() {
        this.instant = null;
    }

    /** 设定当前时刻（仅用于测试/管理侧复算）。 */
    public void setTime(LocalDateTime time) {
        this.instant = time.atZone(zone).toInstant();
    }

    /** 清除固定时刻，恢复跟随系统时钟。 */
    public void reset() {
        this.instant = null;
    }

    public LocalDateTime now() {
        return LocalDateTime.now(this);
    }

    @Override
    public ZoneId getZone() {
        return zone;
    }

    @Override
    public Clock withZone(ZoneId zone) {
        MutableClock c = new MutableClock();
        c.instant = this.instant;
        c.zone = zone;
        return c;
    }

    @Override
    public Instant instant() {
        return instant != null ? instant : Instant.now();
    }

    /** H2/MySQL 均不感知 ZoneOffset，固定使用东八区写入。 */
    public static ZoneOffset fixedOffset() {
        return ZoneOffset.ofHours(8);
    }
}

package com.example.starter.hazmat.config;

import com.example.starter.hazmat.clock.MutableClock;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 公共 Bean 配置：可控时钟。
 */
@Configuration
public class HazmatConfig {

    @Bean
    public MutableClock mutableClock() {
        return new MutableClock();
    }
}

package com.example.starter.hazmat.domain;

/**
 * 运单状态机。
 *
 * <p>流转：APPLIED（已申请）→ ROUTE_APPROVED（路线核准）→ DISPATCHED（发运）
 * → IN_TRANSIT（在途打卡）→ COMPLETED（到达核销结案，终态）。
 * 路线驳回为 ROUTE_REJECTED（终态）；连续 2 点超时升级 LOST_CONTACT（失联终态，并冻结车辆）。
 */
public enum ShipmentStatus {

    /** 已申请，路线待核准。 */
    APPLIED(false),
    /** 路线核准驳回（终态）。 */
    ROUTE_REJECTED(true),
    /** 路线已核准，待发运。 */
    ROUTE_APPROVED(false),
    /** 已发运。 */
    DISPATCHED(false),
    /** 在途（已有打卡或监控扫描）。 */
    IN_TRANSIT(false),
    /** 到达核销结案（唯一正常终态）。 */
    COMPLETED(true),
    /** 失联（唯一异常终态，车辆冻结）。 */
    LOST_CONTACT(true);

    private final boolean terminal;

    ShipmentStatus(boolean terminal) {
        this.terminal = terminal;
    }

    public boolean isTerminal() {
        return terminal;
    }
}

package com.example.starter.hazmat.domain;

/**
 * 运单路线核准记录状态。
 */
public enum RouteApprovalStatus {

    /** 待核准（申请时/紧急改线时写入）。 */
    PENDING,
    /** 已核准（当前生效路线，同一运单至多一条）。 */
    APPROVED,
    /** 核准驳回（类别不匹配、禁行、管制时段冲突等）。 */
    REJECTED,
    /** 已被新核准路线替代而终止（改线生效时原路线写入）。 */
    TERMINATED
}

package com.example.starter.hazmat.domain;

/**
 * 途经点监控状态。
 */
public enum WaypointState {

    /** 未打卡且未超时。 */
    PENDING,
    /** 已超时未打卡（偏离预警）。 */
    TIMED_OUT,
    /** 准点打卡。 */
    CHECKED,
    /** 超时后补打（仍计为已打卡，但保留迟到事实）。 */
    CHECKED_LATE
}

