package com.example.starter.hazmat.api;

import java.time.LocalDateTime;
import java.util.Map;

import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/**
 * 统一错误响应：{ code, message, time }。
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(ApiException.class)
    public ResponseEntity<Map<String, Object>> handle(ApiException ex) {
        return ResponseEntity.status(ex.getStatus()).body(Map.of(
                "code", ex.getCode(),
                "message", ex.getMessage() == null ? "" : ex.getMessage(),
                "time", LocalDateTime.now().toString()));
    }
}

package com.example.starter.hazmat.dto;

import java.time.LocalDateTime;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 运输申请请求。
 *
 * @param requestId       幂等键（申请类）
 * @param vehiclePlate    车牌号
 * @param goodsCategory   危化品类别编码（对应 goods_category 表）
 * @param routeCode       申请通行路线编码
 * @param plannedDeparture 计划发运时刻（Asia/Shanghai），用于推算各途经点计划通过时刻
 */
public record ApplyRequest(
        @NotBlank String requestId,
        @NotBlank String vehiclePlate,
        @NotBlank String goodsCategory,
        @NotBlank String routeCode,
        @NotNull LocalDateTime plannedDeparture) {
}

package com.example.starter.hazmat.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 仅带幂等键的操作请求（发运、核销）。
 */
public record IdempotentRequest(@NotBlank String requestId) {
}

package com.example.starter.hazmat.dto;

import java.time.LocalDateTime;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;

/**
 * 押运打卡请求。
 *
 * @param requestId 幂等键
 * @param waypointSeq 途经点序号（从 0 开始，按路线模板）
 * @param checkTime  实际打卡时刻（Asia/Shanghai）
 */
public record CheckinRequest(
        @NotBlank String requestId,
        @PositiveOrZero int waypointSeq,
        @NotNull LocalDateTime checkTime) {
}

package com.example.starter.hazmat.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 紧急改线申请：为运单申请一条新路线核准；核准通过前原路线打卡继续有效。
 */
public record RerouteRequest(@NotBlank String requestId, @NotBlank String routeCode) {
}

