package com.example.starter.hazmat.po;

/**
 * 危化品类别。
 *
 * @param categoryCode  类别编码
 * @param categoryName  类别名称
 * @param requiredLevel 要求的最低路线通行等级（数字越大管制越严）
 */
public record GoodsCategory(String categoryCode, String categoryName, int requiredLevel) {
}

package com.example.starter.hazmat.po;

/**
 * 路线模板（合成基础数据）。
 *
 * @param routeCode 路线编码
 * @param routeName 路线名称
 * @param passLevel 路线通行等级（须不低于危化品类别要求等级方可核准）
 * @param forbidden 是否禁行路线（禁行一律驳回）
 */
public record RouteInfo(String routeCode, String routeName, int passLevel, boolean forbidden) {
}

package com.example.starter.hazmat.po;

/**
 * 路线模板途经点定义。
 *
 * @param routeCode      所属路线编码
 * @param seq            途经点序号（从 0 起）
 * @param name           途经点名称
 * @param offsetMinutes  相对计划发运时刻的偏移（分钟）；计划通过时刻 = 计划发运 + 偏移
 */
public record RouteWaypointDef(String routeCode, int seq, String name, int offsetMinutes) {
}

package com.example.starter.hazmat.po;

import java.time.LocalDateTime;

/**
 * 管制时段（半开区间 [startTime, endTime)）。
 *
 * @param id        主键
