package com.example.starter.hazmat.api;

import java.time.LocalDateTime;
import java.util.Map;

import jakarta.validation.Valid;

import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import com.example.starter.hazmat.dto.ApplyRequest;
import com.example.starter.hazmat.dto.CheckinRequest;
import com.example.starter.hazmat.dto.IdempotentRequest;
import com.example.starter.hazmat.dto.RerouteRequest;
import com.example.starter.hazmat.service.HazmatService;

/**
 * 危化品运输监管 REST 入口（骨架）。
 */
@RestController
public class HazmatController {

    private final HazmatService service;

    public HazmatController(HazmatService service) {
        this.service = service;
    }

    @PostMapping("/api/shipments/apply")
    public Map<String, Object> apply(@Valid @RequestBody ApplyRequest request) {
        return service.apply(request);
    }

    @PostMapping("/api/shipments/{shipmentNo}/approvals/decide")
    public Map<String, Object> decide(@PathVariable String shipmentNo,
                                      @RequestParam(defaultValue = "true") boolean approved) {
        return service.decideApproval(shipmentNo, approved);
    }

    @PostMapping("/api/shipments/{shipmentNo}/dispatch")
    public Map<String, Object> dispatch(@PathVariable String shipmentNo,
                                        @Valid @RequestBody IdempotentRequest request) {
        return service.dispatch(shipmentNo, request.requestId());
    }

    @PostMapping("/api/shipments/{shipmentNo}/checkins")
    public Map<String, Object> checkin(@PathVariable String shipmentNo,
                                       @Valid @RequestBody CheckinRequest request) {
        return service.checkin(shipmentNo, request);
    }

    @PostMapping("/api/shipments/{shipmentNo}/reroute")
    public Map<String, Object> reroute(@PathVariable String shipmentNo,
                                       @Valid @RequestBody RerouteRequest request) {
        return service.reroute(shipmentNo, request);
    }

    @PostMapping("/api/shipments/{shipmentNo}/approvals/{approvalId}/approve")
    public Map<String, Object> approveReroute(@PathVariable String shipmentNo,
                                              @PathVariable long approvalId) {
        return service.approveReroute(shipmentNo, approvalId);
    }

    @PostMapping("/api/shipments/{shipmentNo}/complete")
    public Map<String, Object> complete(@PathVariable String shipmentNo,
                                        @Valid @RequestBody IdempotentRequest request) {
        return service.complete(shipmentNo, request.requestId());
    }

    @GetMapping("/api/shipments/{shipmentNo}")
    public Map<String, Object> get(@PathVariable String shipmentNo) {
        return service.getShipment(shipmentNo);
    }

    @PostMapping("/api/monitor/scan")
    public Map<String, Object> scan(@RequestParam(required = false) LocalDateTime at) {
        return service.scanTimeouts(at);
    }
}

