    // ---------- 基础数据 ----------

    private static final RowMapper<GoodsCategory> CATEGORY_MAPPER = (rs, n) ->
            new GoodsCategory(rs.getString("category_code"),
                    rs.getString("category_name"), rs.getInt("required_level"));

