        ServiceResultShim result = new ServiceResultShim(checkin(no, "c-late-ck", 0, DEPARTURE.plusMinutes(40)));
        assertThat(result.status).isEqualTo("COMPLETED");
        assertThat(result.lateAfterClosed).isEqualTo(true);
