        assertThat(view(no).get("status")).isEqualTo("LOST_CONTACT");
        assertThatThrownBy(() -> complete(no, "c-done-after-lost"))
                .isInstanceOf(ApiException.class)
                .satisfies(e -> assertThat(((ApiException) e).getCode()).isEqualTo("ALREADY_LOST_CONTACT"));
    }

    /**
     * 核销与失联冻结并发：多线程同时 complete 与 scan（触发失联），
     * 数据库条件更新保证唯一终态——不得既 COMPLETED 又 LOST_CONTACT。
     */
    @Test
    void completeAndLostContactRaceYieldsSingleTerminal() throws Exception {
        // 准备一辆连续两点超时的在途运单（不预先扫描，留给并发触发）。
        String no = dispatchedInTransit("沪A-1001", "c-race");
        LocalDateTime lostAt = LocalDateTime.parse("2026-10-02T10:00:00");

        int completeWins = 0;
        int lostWins = 0;
        // 重复若干轮以提高竞态覆盖；每轮重新构造一个在途运单。
        for (int round = 0; round < 8; round++) {
            String plate = round % 2 == 0 ? "沪A-1001" : "沪A-1002";
            if (round > 0) {
                no = dispatchedInTransit(plate, "c-race-" + round);
            }
            CountDownLatch start = new CountDownLatch(1);
            AtomicReference<String> completeOutcome = new AtomicReference<>("none");
            AtomicReference<String> scanOutcome = new AtomicReference<>("none");
            ExecutorService pool = Executors.newFixedThreadPool(2);
            try {
                pool.submit(() -> {
                    await(start);
                    try {
                        complete(no, "c-race-done-" + round);
                        completeOutcome.set("COMPLETED");
                    } catch (ApiException e) {
                        completeOutcome.set("REJECTED:" + e.getCode());
                    }
                });
                pool.submit(() -> {
                    await(start);
                    try {
                        var r = scan(lostAt);
                        @SuppressWarnings("unchecked")
                        java.util.List<java.util.Map<String, Object>> affected =
                                (java.util.List<java.util.Map<String, Object>>) r.body().get("affected");
                        boolean lost = affected.stream()
                                .anyMatch(a -> no.equals(a.get("shipmentNo")) && Boolean.TRUE.equals(a.get("lostContact")));
                        scanOutcome.set(lost ? "LOST" : "NOT_LOST");
                    } catch (RuntimeException e) {
                        scanOutcome.set("ERROR");
                    }
                });
                start.countDown();
            } finally {
                pool.shutdown();
                assertThat(pool.awaitTermination(20, TimeUnit.SECONDS)).isTrue();
            }

            String finalStatus = (String) view(no).get("status");
            // 唯一终态断言：状态必须是二者之一，且数据自洽。
            assertThat(finalStatus).isIn("COMPLETED", "LOST_CONTACT");
            boolean frozen = repository.findVehicle(no == null ? plate : plateOf(no)).orElseThrow().frozen();
            if ("COMPLETED".equals(finalStatus)) {
                completeWins++;
                // 核销赢家：车辆不得被本运单冻结、占用已释放。
                assertThat(scanOutcome.get()).isEqualTo("NOT_LOST");
            } else {
                lostWins++;
                assertThat(frozen).isTrue();
                assertThat(completeOutcome.get()).startsWith("REJECTED");
            }
        }
        // 至少各出现一次，证明两条路径都真实参与过竞争。
        assertThat(completeWins).isGreaterThan(0);
        assertThat(lostWins).isGreaterThan(0);
    }

    private static void await(CountDownLatch latch) {
        try {
            latch.await();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private String plateOf(String shipmentNo) {
        return (String) view(shipmentNo).get("vehiclePlate");
    }

    /** 小辅助，便于读取结案后打卡响应字段。 */
    private static final class ServiceResultShim {
        final String status;
        final boolean lateAfterClosed;

        @SuppressWarnings("unchecked")
        ServiceResultShim(com.example.starter.hazmat.service.ServiceResult result) {
            this.status = (String) result.body().get("status");
            this.lateAfterClosed = Boolean.TRUE.equals(result.body().get("lateAfterClosed"));
        }
    }
}

