        assertThatThrownBy(() -> complete(no, "c-done-after-lost"))
                .isInstanceOf(ApiException.class)
                .satisfies(e -> assertThat(((ApiException) e).getCode()).isEqualTo("ALREADY_LOST_CONTACT"));
    }

    @Test
    void completedShipmentIsNotFrozenByLaterScan() {
